package com.vinnyvangogh.buildguard;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.annotations.SerializedName;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Every quest, with what it needs and what it grants.
 *
 * <p>Bundled as a jar resource and generated by questpath's
 * {@code -export-quest-graph}. Nobody transcribes 218 quests by hand, and the
 * bundle is what lets this plugin answer with no server and no network of any
 * kind. It goes stale by design: the graph updates when this plugin is
 * released, not when the wiki changes.
 *
 * <p><b>This is a deliberately narrow reading of a wider document.</b> The
 * bundle is questpath's full export and carries a great deal Build Guard has
 * no use for — a 166-row shop table, a 1,301-row item catalogue with sources
 * and drop locations, achievement diary tasks, and each quest's start
 * coordinates. Every one of those serves a feature that is out of scope here
 * (shop run, diaries, routing; see {@code BRIEF.md}), so the model below omits
 * them and Gson ignores the keys. Two consequences worth knowing before
 * reaching for one:
 *
 * <ul>
 * <li>Anything omitted is one field and one accessor away — the data is in the
 *     jar already. {@code quest.members} is the likeliest to be wanted and is
 *     left out only because the classifier never reads it.
 * <li>Trimming is <em>not</em> a licence to loosen {@link #parse}. A field this
 *     class does not model is a field it does not depend on; a field it does
 *     model and reads as absent is the hazard the version gate exists for.
 * </ul>
 */
class QuestGraph
{
	/**
	 * The graph shape this build understands.
	 *
	 * <p>A version it does not know is refused rather than parsed, and this
	 * check is load-bearing. A graph missing a field parses cleanly into nulls
	 * and then answers "eligible" for a quest whose requirements were never
	 * read — a confident wrong answer, which is the one thing this plugin must
	 * not produce. Here that costs experience, and experience does not come
	 * back.
	 *
	 * <p>The number is questpath's, not Build Guard's, and it stays honest: 12
	 * is what {@code -export-quest-graph} currently emits. Of the bumps behind
	 * it, the two this plugin genuinely depends on are <b>5</b>, which added
	 * {@link #boosts()} — a requirement's {@code boostable} flag permits a
	 * boost and never says how large one can be, so a bundle without the boost
	 * table cannot tell a one-level shortfall from a fifty-level one — and
	 * <b>6</b>, which added {@code prerequisites_started_only}: without it a
	 * quest that need only be <em>begun</em> is demanded complete, blocking
	 * something the account can genuinely do. The rest (2–4, 7–12) added
	 * shops, items, coordinates and diary tasks, none of which this class
	 * reads.
	 */
	static final int SUPPORTED_VERSION = 12;

	@SerializedName("version")
	private int version;

	@SerializedName("quests")
	private List<Quest> quests;

	@SerializedName("boosts")
	private List<Boost> boosts;

	/**
	 * One temporary skill boost, with the size the requirement flag never had.
	 *
	 * A requirement's {@code boostable} is a bare yes from the wiki: it says a
	 * boost is allowed and never how large one can be. Without these, a
	 * fifty-level shortfall and a one-level shortfall are indistinguishable,
	 * which is the bug they exist to close.
	 */
	static class Boost
	{
		@SerializedName("skill")
		private String skill;

		@SerializedName("item")
		private String item;

		@SerializedName("base")
		private int base;

		@SerializedName("per_level")
		private double perLevel;

		@SerializedName("max")
		private int max;

		@SerializedName("random")
		private boolean random;

		String skill()
		{
			return skill == null ? "" : skill;
		}

		String item()
		{
			return item == null ? "" : item;
		}

		/** The increase at level 0, or the whole increase when flat. */
		int base()
		{
			return base;
		}

		/** The fraction of the account's level added on top; zero when flat. */
		double perLevel()
		{
			return perLevel;
		}

		/** The wiki's stated ceiling, or zero when it states one number. */
		int max()
		{
			return max;
		}

		/** Whether this one can drain instead of boosting -- the stews. */
		boolean random()
		{
			return random;
		}
	}

	/** One quest as the verdict engine sees it. */
	static class Quest
	{
		@SerializedName("id")
		private long id;

		@SerializedName("slug")
		private String slug;

		@SerializedName("name")
		private String name;

		@SerializedName("prerequisites")
		private List<Long> prerequisites;

		@SerializedName("prerequisites_started_only")
		private List<Long> prerequisitesStartedOnly;

		@SerializedName("requirements")
		private List<Requirement> requirements;

		@SerializedName("rewards")
		private List<Reward> rewards;

		/**
		 * questpath's own row id. Never the client's: {@code
		 * net.runelite.api.Quest} ids are the game's and these are questpath's
		 * SQLite rowids, two id spaces with nothing to do with each other. The
		 * generated vectors speak this one, and {@link PlayerState} matches
		 * completion by name for exactly that reason.
		 */
		long id()
		{
			return id;
		}

		String slug()
		{
			return slug == null ? "" : slug;
		}

		String name()
		{
			return name == null ? "" : name;
		}

		List<Long> prerequisites()
		{
			return prerequisites == null ? Collections.emptyList() : prerequisites;
		}

		/**
		 * The subset of {@link #prerequisites()} satisfied by having *started*
		 * the quest rather than finished it -- the wiki's "Started [[X]]"
		 * phrasing. Both planners must apply this identically or their verdicts
		 * diverge, which is what PlannerVectorsTest exists to catch.
		 */
		boolean requiresStartedOnly(long prerequisiteId)
		{
			if (prerequisitesStartedOnly == null)
			{
				return false;
			}
			return prerequisitesStartedOnly.contains(prerequisiteId);
		}

		List<Requirement> requirements()
		{
			return requirements == null ? Collections.emptyList() : requirements;
		}

		List<Reward> rewards()
		{
			return rewards == null ? Collections.emptyList() : rewards;
		}
	}

	/** A skill level a quest demands. */
	static class Requirement
	{
		@SerializedName("skill")
		private String skill;

		@SerializedName("level")
		private int level;

		@SerializedName("boostable")
		private boolean boostable;

		String skill()
		{
			return skill == null ? "" : skill;
		}

		int level()
		{
			return level;
		}

		/**
		 * Boostable rescues a skill gap but never a cap violation: a boost is
		 * relative to the base level, so an Attack capped at 1 cannot reach a
		 * boostable requirement of 15.
		 */
		boolean boostable()
		{
			return boostable;
		}
	}

	/**
	 * Unavoidable experience a quest grants.
	 *
	 * <p>Unavoidable is the whole point, and it is decided by the exporter
	 * rather than here: questpath's {@code internal/export/questgraph.go}
	 * carries "only unavoidable experience — the rewards the build guard can
	 * actually block on. Lamps and optional rewards are choices, and a choice
	 * cannot break a cap unless you make it." So every reward in this list is
	 * forced XP, and {@link QuestClassifier} may block on all of them without
	 * having to ask which were optional.
	 */
	static class Reward
	{
		@SerializedName("skill")
		private String skill;

		@SerializedName("xp")
		private double xp;

		String skill()
		{
			return skill == null ? "" : skill;
		}

		double xp()
		{
			return xp;
		}
	}

	private Map<Long, Quest> byId;
	private Map<String, Quest> byName;

	int version()
	{
		return version;
	}

	List<Quest> quests()
	{
		return quests == null ? Collections.emptyList() : quests;
	}

	/** Every temporary skill boost the bundle carries. */
	List<Boost> boosts()
	{
		return boosts == null ? Collections.emptyList() : boosts;
	}

	/** One quest by id, or null when the graph does not carry it. */
	Quest get(long id)
	{
		if (byId == null)
		{
			Map<Long, Quest> index = new LinkedHashMap<>();
			for (Quest quest : quests())
			{
				index.put(quest.id(), quest);
			}
			byId = index;
		}
		return byId.get(id);
	}

	/**
	 * One quest by its exact name, or null when the graph does not carry it.
	 *
	 * Names rather than ids because that is what the client speaks: {@code
	 * net.runelite.api.Quest#getName()} is a game-name string, never one of
	 * questpath's rowids, and comparing the two id spaces produced a completed
	 * set that was pure coincidence.
	 */
	Quest byName(String name)
	{
		if (byName == null)
		{
			Map<String, Quest> index = new LinkedHashMap<>();
			for (Quest quest : quests())
			{
				index.put(quest.name(), quest);
			}
			byName = index;
		}
		return byName.get(name);
	}

	/**
	 * Loads the bundled graph.
	 *
	 * <p>{@code getResourceAsStream}, never {@code getResource}: resources ship
	 * inside a jar, and a URL to one is not a file path.
	 *
	 * @param gson an injected Gson. This class never constructs one; see
	 *     {@code AGENTS.md}.
	 * @throws IOException when the resource is missing, unreadable, or carries a
	 *     version this build does not understand
	 */
	static QuestGraph load(Gson gson) throws IOException
	{
		try (InputStream stream = QuestGraph.class.getResourceAsStream("quests.json"))
		{
			if (stream == null)
			{
				throw new IOException("bundled quests.json is missing from the jar");
			}
			try
			{
				return parse(gson, new InputStreamReader(stream, StandardCharsets.UTF_8));
			}
			catch (IOException e)
			{
				throw new IOException("bundled quests.json: " + e.getMessage(), e);
			}
		}
	}

	/**
	 * Parses and validates a graph document already in hand: it must parse, name
	 * a version this build understands, and carry at least one quest.
	 *
	 * <p>Separate from {@link #load(Gson)} so a document can be held to exactly
	 * these rules in a test without going through the jar. It is <b>not</b> a
	 * door for a graph fetched over the network — this plugin makes no requests
	 * at all, and questpath's {@code QuestGraphFetcher} is deliberately not
	 * ported.
	 *
	 * @throws IOException when the document does not parse, or parses to a
	 *     version this build does not understand, or carries no quests
	 */
	static QuestGraph parse(Gson gson, Reader reader) throws IOException
	{
		QuestGraph graph;
		try
		{
			graph = gson.fromJson(reader, QuestGraph.class);
		}
		catch (JsonSyntaxException e)
		{
			throw new IOException("did not parse as a quest graph: " + e.getMessage(), e);
		}
		if (graph == null)
		{
			throw new IOException("did not parse as a quest graph");
		}
		if (graph.version() != SUPPORTED_VERSION)
		{
			throw new IOException(graph.version() > SUPPORTED_VERSION
				? "is version " + graph.version() + ", which this build (" + SUPPORTED_VERSION
					+ ") does not understand yet -- update the plugin"
				: "is version " + graph.version() + ", which is older than this build ("
					+ SUPPORTED_VERSION + ") expects -- the bundle needs re-exporting");
		}
		if (graph.quests().isEmpty())
		{
			// An empty graph makes every quest unknown, which renders as
			// "not found" rather than as "the graph is broken".
			throw new IOException("carries no quests");
		}
		return graph;
	}
}
